    fun byTopic(t: Topic): List<Lesson> = all.filter { it.topic == t }

    /** The same lesson all day, a new one tomorrow. */
    fun forDay(dayNumber: Long): Lesson = all[(Math.floorMod(dayNumber * 7 + 3, all.size.toLong())).toInt()]
}
